// Edit daftar ini: nama, kategori, deskripsi singkat, dan nama file foto di folder "foto/"
  // Jika foto tidak ketemu, coba nama/ekstensi lain (huruf besar-kecil, .jpg/.jpeg/.png/.webp)
function imgFallback(img){
  if(!img.dataset.cands){
    const base=img.getAttribute("src").replace(/^foto\//,"").replace(/\.[^.]+$/,"");
    const names=[base,base.toLowerCase(),base.charAt(0).toUpperCase()+base.slice(1).toLowerCase()];
    const exts=["jpg","jpeg","png","webp","JPG","JPEG","PNG"];
    const c=[]; names.forEach(nm=>exts.forEach(e=>c.push("foto/"+nm+"."+e)));
    img.dataset.cands=JSON.stringify([...new Set(c)]); img.dataset.i="0";
  }
  const c=JSON.parse(img.dataset.cands), i=+img.dataset.i;
  if(i<c.length){img.dataset.i=i+1; img.src=c[i];} else img.remove();
}

