// ===== Lightbox: klik foto untuk lihat full =====
const lb=document.getElementById("lb"),lbimg=document.getElementById("lbimg"),lbcap=document.getElementById("lbcap");
let list=[],idx=0;
function show(i){
  idx=(i+list.length)%list.length;
  lbimg.src=list[idx].dataset.src; lbimg.alt=list[idx].dataset.cap; lbcap.textContent=list[idx].dataset.cap;
}
function openLb(el){
  list=[...document.querySelectorAll(".zoomable")].filter(z=>z.querySelector("img"));
  show(list.indexOf(el)); lb.classList.add("open"); lb.setAttribute("aria-hidden","false"); document.body.style.overflow="hidden";
}
function closeLb(){lb.classList.remove("open"); lb.setAttribute("aria-hidden","true"); document.body.style.overflow="";}
document.addEventListener("click",e=>{
  if(document.fullscreenElement) return;
  const z=e.target.closest(".zoomable"); if(z && z.querySelector("img")) openLb(z);
});
document.getElementById("lbx").onclick=closeLb;
document.getElementById("lbp").onclick=e=>{e.stopPropagation();show(idx-1)};
document.getElementById("lbn").onclick=e=>{e.stopPropagation();show(idx+1)};
lb.addEventListener("click",e=>{if(e.target===lb)closeLb()});
document.addEventListener("keydown",e=>{
  if(!lb.classList.contains("open"))return;
  if(e.key==="Escape")closeLb(); if(e.key==="ArrowLeft")show(idx-1); if(e.key==="ArrowRight")show(idx+1);
});
// swipe di HP
let sx=0; lb.addEventListener("touchstart",e=>{sx=e.touches[0].clientX},{passive:true});
lb.addEventListener("touchend",e=>{const d=e.changedTouches[0].clientX-sx; if(Math.abs(d)>50)show(d>0?idx-1:idx+1)});

// ===== Muncul pelan saat di-scroll =====
const io=new IntersectionObserver(es=>es.forEach(en=>{if(en.isIntersecting){en.target.classList.add("in");io.unobserve(en.target)}}),{threshold:.15});
document.querySelectorAll(".rv").forEach((el,i)=>{el.style.transitionDelay=(i%4)*90+"ms";io.observe(el)});

// ===== Slider hero: otomatis, bingkai menyesuaikan ukuran foto =====
(function(){
  const slider=document.getElementById("slider"); if(!slider) return;
  const slides=[...slider.querySelectorAll(".slide")], n=slides.length;
  const dots=document.getElementById("slDots"), bar=document.getElementById("slBar");
  const cap=document.getElementById("slCap"), num=document.getElementById("slNum"), wa=document.getElementById("slWa");
  const bg=document.getElementById("heroBg");
  const DELAY=3500; // jeda antar foto (milidetik)
  let cur=0,timer;

  // latar buram dari foto yang sedang tampil
  const bgs=slides.map(s=>{const i=document.createElement("i");i.style.backgroundImage='url("'+s.dataset.src+'")';bg.appendChild(i);return i});
  for(let i=0;i<n;i++){const b=document.createElement("button");b.setAttribute("aria-label","Foto "+(i+1));b.onclick=()=>{go(i);restart()};dots.appendChild(b)}

  // bingkai mengikuti rasio foto -> foto utuh & tidak ada ruang kosong
  function layout(){
    if(document.fullscreenElement===slider){slider.style.width="";slider.style.height="";return}
    const img=slides[cur].querySelector("img");
    const r=(img&&img.naturalWidth)?img.naturalWidth/img.naturalHeight:4/3;
    const W=slider.parentElement.clientWidth;
    const H=Math.max(260,window.innerHeight*(window.innerWidth<=860?0.6:0.74));
    const w=Math.min(W,H*r);
    slider.style.width=w+"px"; slider.style.height=(w/r)+"px";
  }
  slides.forEach(s=>{const img=s.querySelector("img"); if(img) img.addEventListener("load",()=>{ if(slides[cur]===s) layout() })});
  window.addEventListener("resize",layout);
  document.addEventListener("fullscreenchange",layout);

  function go(i){
    cur=(i+n)%n;
    slides.forEach((s,k)=>s.classList.toggle("active",k===cur));
    bgs.forEach((b,k)=>b.classList.toggle("on",k===cur));
    [...dots.children].forEach((d,k)=>d.classList.toggle("on",k===cur));
    const name=slides[cur].dataset.cap||"";
    cap.textContent=name;
    num.textContent=String(cur+1).padStart(2,"0")+" / "+String(n).padStart(2,"0");
    wa.href="https://wa.me/+62 811-1118-08893?text="+encodeURIComponent("Halo Mega Daihatsu, saya tertarik dengan "+name+". Boleh info promo & simulasi kreditnya?");
    layout();
  }
  function restart(){
    clearInterval(timer);
    bar.classList.remove("run"); void bar.offsetWidth; bar.classList.add("run");
    timer=setInterval(()=>{go(cur+1);bar.classList.remove("run");void bar.offsetWidth;bar.classList.add("run")},DELAY);
  }
  document.getElementById("slPrev").onclick=()=>{go(cur-1);restart()};
  document.getElementById("slNext").onclick=()=>{go(cur+1);restart()};
  let sx=0;
  slider.addEventListener("touchstart",e=>{sx=e.touches[0].clientX},{passive:true});
  slider.addEventListener("touchend",e=>{const d=e.changedTouches[0].clientX-sx;if(Math.abs(d)>40){go(d>0?cur-1:cur+1);restart()}});
  document.addEventListener("visibilitychange",()=>{document.hidden?clearInterval(timer):restart()});
  document.addEventListener("keydown",e=>{
    if(document.getElementById("lb").classList.contains("open")) return;
    if(e.key==="ArrowLeft"){go(cur-1);restart()} if(e.key==="ArrowRight"){go(cur+1);restart()}
  });
  const fs=document.getElementById("slFs");
  fs.onclick=e=>{e.stopPropagation(); if(document.fullscreenElement) document.exitFullscreen(); else if(slider.requestFullscreen) slider.requestFullscreen(); else if(slider.webkitRequestFullscreen) slider.webkitRequestFullscreen();};
  go(0);restart();
})();